insert into public.site_posts (slug, sort_order, category, title, excerpt, images, body) values
  ($mcc$ket-qua-thi-hsk-18-07-2026$mcc$, 1, $mcc$Thành tích HSK$mcc$, $mcc$Khi HSK không chỉ là học để đủ điểm đỗ$mcc$, $mcc$Kỳ thi HSK ngày 18/07/2026: bốn bạn đạt 292/300 HSK3, trong đó hai bạn chỉ sau 2,5 tháng học lớp cấp tốc.$mcc$, $mcc$[{"src":"stories/ket-qua-hsk-18-07-2026/1.webp","alt":"Kết quả thi HSK ngày 18/07/2026 của học viên MCC — ảnh 1"},{"src":"stories/ket-qua-hsk-18-07-2026/2.webp","alt":"Kết quả thi HSK ngày 18/07/2026 của học viên MCC — ảnh 2"},{"src":"stories/ket-qua-hsk-18-07-2026/3.webp","alt":"Kết quả thi HSK ngày 18/07/2026 của học viên MCC — ảnh 3"},{"src":"stories/ket-qua-hsk-18-07-2026/4.webp","alt":"Kết quả thi HSK ngày 18/07/2026 của học viên MCC — ảnh 4"},{"src":"stories/ket-qua-hsk-18-07-2026/5.webp","alt":"Kết quả thi HSK ngày 18/07/2026 của học viên MCC — ảnh 5"},{"src":"stories/ket-qua-hsk-18-07-2026/6.webp","alt":"Kết quả thi HSK ngày 18/07/2026 của học viên MCC — ảnh 6"},{"src":"stories/ket-qua-hsk-18-07-2026/7.webp","alt":"Kết quả thi HSK ngày 18/07/2026 của học viên MCC — ảnh 7"},{"src":"stories/ket-qua-hsk-18-07-2026/8.webp","alt":"Kết quả thi HSK ngày 18/07/2026 của học viên MCC — ảnh 8"}]$mcc$::jsonb, $mcc$[{"kind":"lead","text":"Trong kỳ thi HSK ngày 18/07/2026 vừa qua, các học viên MCC đã chính thức nhận về những kết quả thật đáng tự hào. Đằng sau mỗi con số là cả một quá trình học tập, ôn luyện chăm chỉ của các bạn và sự đồng hành sát sao của giáo viên MCC."},{"kind":"paragraph","text":"Cùng MCC vinh danh những gương mặt xuất sắc của trung tâm trong kỳ thi HSK vừa qua:"},{"kind":"results","items":[{"name":"Đỗ Khánh Linh","level":"HSK3","score":"292/300","note":"Sau 2,5 tháng học lớp HSK1-3 cấp tốc"},{"name":"Nguyễn Ngọc Hà","level":"HSK3","score":"292/300","note":"Sau 2,5 tháng học lớp HSK1-3 cấp tốc"},{"name":"Khánh Huyền","level":"HSK3","score":"292/300"},{"name":"Mai Linh","level":"HSK3","score":"292/300"},{"name":"Tùng Dương","level":"HSK3","score":"278/300"},{"name":"Trương Hồng Phúc","level":"HSK3","score":"226/300"},{"name":"Minh Nguyệt","level":"HSK4","score":"234/300"}]},{"kind":"paragraph","text":"Điều MCC vui nhất không chỉ là nhìn thấy những con số trên bảng điểm, mà còn là được chúc mừng những nỗ lực và sự tiến bộ của từng học viên."},{"kind":"list","items":["Trên lớp, các bạn được học theo lộ trình, củng cố kiến thức và làm quen với dạng bài HSK.","Ngoài giờ học, học viên vẫn có thể trao đổi, hỏi bài và nhận thêm hỗ trợ trong quá trình ôn tập.","Quan trọng nhất vẫn là sự chủ động, chăm chỉ và nỗ lực của mỗi bạn trong suốt hành trình học tập."]},{"kind":"paragraph","text":"Và dù học ONLINE hay OFFLINE, MCC vẫn mong muốn mang đến một môi trường học tập chất lượng để các bạn yên tâm theo đuổi mục tiêu của mình."},{"kind":"paragraph","text":"Một lần nữa, chúc mừng tất cả các học viên MCC đã hoàn thành kỳ thi và đạt được những kết quả thật đáng tự hào! Cảm ơn các bạn đã lựa chọn MCC trên hành trình chinh phục tiếng Trung. Chúc các bạn sẽ tiếp tục giữ vững tinh thần này và chinh phục những cột mốc tiếp theo!"}]$mcc$::jsonb),
  ($mcc$nguoi-di-lam-hoc-hsk5$mcc$, 2, $mcc$Câu chuyện học viên$mcc$, $mcc$Câu chuyện người đi làm học HSK5$mcc$, $mcc$Chị Yến Ngọc bắt đầu từ con số 0, vừa đi làm vừa học và đã cầm trên tay tấm bằng HSK5.$mcc$, $mcc$[{"src":"stories/hsk5-yen-ngoc/1.webp","alt":"Kết quả HSK5 và tin nhắn của chị Yến Ngọc — ảnh 1"},{"src":"stories/hsk5-yen-ngoc/2.webp","alt":"Kết quả HSK5 và tin nhắn của chị Yến Ngọc — ảnh 2"},{"src":"stories/hsk5-yen-ngoc/3.webp","alt":"Kết quả HSK5 và tin nhắn của chị Yến Ngọc — ảnh 3"}]$mcc$::jsonb, $mcc$[{"kind":"lead","text":"Theo bạn, người đi làm bận rộn có thể học tiếng Trung không? Điều quan trọng nhất để chinh phục một ngôn ngữ khó như tiếng Trung là gì?"},{"kind":"paragraph","text":"Không phải là năng khiếu bẩm sinh, cũng chẳng phải là việc bạn có toàn bộ thời gian trong ngày chỉ để ngồi vào bàn học. Điều quan trọng nhất, có lẽ là sự kiên trì ngay cả những lúc lịch trình của bạn bận rộn nhất."},{"kind":"paragraph","text":"MCC đồng hành cùng chị Yến Ngọc từ những ngày đầu tiên, khi chị bắt đầu từ con số 0 tròn trĩnh. Suốt chặng đường dài đó, chị vừa đi làm, vừa học. Có những khoảng thời gian công việc bận rộn, dù phải di chuyển nhiều nhưng chị vẫn đều đặn đến lớp offline. Sự nỗ lực lặng lẽ đó là điều mà tập thể giáo viên và đội ngũ MCC luôn cực kỳ trân trọng."},{"kind":"paragraph","text":"Khi lên lớp HSK5.002, chị chuyển sang học lớp online trực tiếp với giáo viên người Trung Quốc. Ở cấp độ HSK5, lượng từ vựng và ngữ pháp đã tăng lên rất nhiều. Nhưng chính nhờ nền tảng vững từ đầu kết hợp với môi trường tương tác 100% tiếng Trung, kỹ năng nghe và nói của chị tiến bộ rõ rệt qua từng buổi học. Chị nghe tự nhiên hơn, nói trôi chảy và chủ động hơn rất nhiều."},{"kind":"paragraph","text":"Nhìn lại cả một chặng đường dài từ HSK1 đến khi cầm trên tay tấm bằng HSK5, MCC thật sự rất xúc động và tự hào."},{"kind":"paragraph","text":"Chúc mừng chị Yến Ngọc đã hoàn thành xuất sắc mục tiêu của mình. Cảm ơn chị vì đã tin tưởng và chọn MCC làm người đồng hành từ những bước chân đầu tiên!"}]$mcc$::jsonb),
  ($mcc$hoc-vien-dat-hsk6$mcc$, 3, $mcc$Câu chuyện học viên$mcc$, $mcc$Giáo viên HSK6 có học viên đạt HSK6 là cảm giác như thế nào?$mcc$, $mcc$Từ những buổi phát âm b, p, m đầu tiên cuối năm 2023, Tường Vân đã chinh phục HSK6 với 216/300 điểm.$mcc$, $mcc$[{"src":"stories/hsk6-tuong-van/1.webp","alt":"Hành trình HSK6 của Tường Vân — ảnh 1"},{"src":"stories/hsk6-tuong-van/2.webp","alt":"Hành trình HSK6 của Tường Vân — ảnh 2"},{"src":"stories/hsk6-tuong-van/3.webp","alt":"Hành trình HSK6 của Tường Vân — ảnh 3"},{"src":"stories/hsk6-tuong-van/4.webp","alt":"Hành trình HSK6 của Tường Vân — ảnh 4"},{"src":"stories/hsk6-tuong-van/5.webp","alt":"Hành trình HSK6 của Tường Vân — ảnh 5"}]$mcc$::jsonb, $mcc$[{"kind":"lead","text":"Đó là cảm giác như nhìn thấy một hạt giống nhỏ bé mình gieo từ cuối năm 2023… hôm nay nở thành một bông hoa rực rỡ."},{"kind":"paragraph","text":"Cuối năm 2023, Tường Vân bắt đầu tiếng Trung từ con số 0, bước những bước chân đầu tiên dưới sự dẫn dắt của “chị giáo” Lưu Ngọc Mai. Từ những buổi học phát âm b, p, m đầu tiên, vậy mà sau hơn 1 năm kiên trì, bền bỉ, hôm nay em đã xuất sắc chinh phục HSK6 với 216/300 điểm – một cột mốc mà nhiều người học tiếng Trung cũng mơ ước."},{"kind":"paragraph","text":"Trong suốt hành trình đó, Vân luôn là cô học viên chăm chỉ, tham gia học và nộp bài đầy đủ, còn luôn chủ động hỏi thêm, tìm hiểu sâu hơn về bài nữa. Và rồi những nỗ lực thầm lặng ấy đã kết trái."},{"kind":"paragraph","text":"Không chỉ là điểm số — đây là một dấu mốc trưởng thành, là minh chứng cho hành trình học thuật bền bỉ mà đội ngũ MCC luôn tự hào được đồng hành cùng học viên."},{"kind":"paragraph","text":"Cảm ơn Vân vì đã tin tưởng và lựa chọn đồng hành cùng “chị giáo”. Cảm ơn vì đã chứng minh rằng: chỉ cần đủ quyết tâm, tiếng Trung không hề khó – chỉ cần ta đừng bỏ cuộc."},{"kind":"paragraph","text":"Chúc mừng em, Phan Nguyễn Tường Vân. Chặng đường HSK6 chỉ là khởi đầu — phía trước còn rất nhiều cánh cửa đẹp đang đợi em mở ra."}]$mcc$::jsonb),
  ($mcc$khong-khi-lop-hoc-offline$mcc$, 4, $mcc$Lớp học MCC$mcc$, $mcc$Không khí lớp học offline tại MCC luôn vô cùng sôi động!$mcc$, $mcc$Luyện nói ngay từ đầu giờ, tương tác suốt buổi học và thực hành lại kiến thức vào cuối buổi.$mcc$, $mcc$[{"src":"stories/lop-hoc-offline/1.webp","alt":"Lớp học offline tại MCC — ảnh 1"},{"src":"stories/lop-hoc-offline/2.webp","alt":"Lớp học offline tại MCC — ảnh 2"},{"src":"stories/lop-hoc-offline/3.webp","alt":"Lớp học offline tại MCC — ảnh 3"},{"src":"stories/lop-hoc-offline/4.webp","alt":"Lớp học offline tại MCC — ảnh 4"},{"src":"stories/lop-hoc-offline/5.webp","alt":"Lớp học offline tại MCC — ảnh 5"},{"src":"stories/lop-hoc-offline/6.webp","alt":"Lớp học offline tại MCC — ảnh 6"},{"src":"stories/lop-hoc-offline/7.webp","alt":"Lớp học offline tại MCC — ảnh 7"}]$mcc$::jsonb, $mcc$[{"kind":"lead","text":"Tại MCC, các bạn không chỉ học từ vựng, ngữ pháp mà còn được luyện nói và giao tiếp ngay từ đầu giờ, cùng nhau tương tác trong suốt buổi học và thực hành lại kiến thức vào cuối buổi."},{"kind":"paragraph","text":"Mỗi buổi học là một cơ hội để các bạn nói nhiều hơn, phản xạ nhanh hơn và tự tin sử dụng tiếng Trung hơn."},{"kind":"paragraph","text":"Cùng xem một chút “vibe” lớp học nhà MCC nhé!"}]$mcc$::jsonb),
  ($mcc$cuoc-thi-viet-chu-han-tet$mcc$, 5, $mcc$Hoạt động$mcc$, $mcc$Cuộc thi viết chữ Hán Tết: 笔墨迎春 – Xuân trong nét chữ$mcc$, $mcc$Bài dự thi của học viên Phạm Bình Phương Khuê.$mcc$, $mcc$[{"src":"stories/chu-han-tet-2026/1.webp","alt":"Bài dự thi viết chữ Hán Tết của Phạm Bình Phương Khuê — ảnh 1"}]$mcc$::jsonb, $mcc$[{"kind":"lead","text":"Cuộc thi viết chữ Hán Tết 笔墨迎春 – Xuân trong nét chữ."},{"kind":"paragraph","text":"Họ và tên học viên: Phạm Bình Phương Khuê."}]$mcc$::jsonb)
